// Product images generated by `scripts/gen_images.py` into `data/images/`,
// copied to `public/images/` before dev and build. A product picks one by
// category and ID with the same rule as `topcoat/src/images.rs`:
// `{category_slug}-{(id % VARIANTS) + 1}.jpg`.
import type { Product } from "./catalog";

/** Images generated per category. */
export const VARIANTS = 3;

/** Pixel size of every generated image (square originals). */
export const IMAGE_SIZE = 1600;

const CATEGORIES = new Set([
  "audio",
  "displays",
  "peripherals",
  "storage",
  "networking",
  "cameras",
  "wearables",
  "smart-home",
]);

/** The image path for `product`, or `null` for a category without images. */
export function productImage(product: Product): string | null {
  if (!CATEGORIES.has(product.category_slug)) {
    return null;
  }
  return `/images/${product.category_slug}-${(product.id % VARIANTS) + 1}.jpg`;
}
